def _generators_folder_with_name(client, name_token, include_release_subdir=False):
    """Return path to generators folder depending on platform and build layout.
    include_release_subdir=True for single-config with no user_defined_build, so 'Release' subfolder exists.
    """
    if platform.system() == "Windows":
        return os.path.join(client.current_folder, "build", name_token, "generators")
    else:
        parts = [client.current_folder, "build", name_token]
        if include_release_subdir:
            parts += ["Release", "generators"]
        else:
            parts += ["generators"]
        return os.path.join(*parts)
